changeSet.sql:
CREATE TABLE bng.baseline_vertical_habitats (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiLineString, 27700) NOT NULL
);

CREATE INDEX idx_baseline_vertical_habitats_project_id
    ON bng.baseline_vertical_habitats (project_id);

CREATE INDEX idx_baseline_vertical_habitats_geom
    ON bng.baseline_vertical_habitats USING GIST (geom);

CREATE TABLE bng.post_intervention_vertical_habitats (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiLineString, 27700) NOT NULL
);

CREATE INDEX idx_post_intervention_vertical_habitats_project_id
    ON bng.post_intervention_vertical_habitats (project_id);

CREATE INDEX idx_post_intervention_vertical_habitats_geom
    ON bng.post_intervention_vertical_habitats USING GIST (geom);
